#!/usr/bin/env bash
# Build the Rust protocol core (Core/carrier-core) for Android and generate its Kotlin bindings.
# Produces:
#   Apps/Android/app/src/main/jniLibs/<abi>/libcarrier_core.so   arm64-v8a, armeabi-v7a, x86_64
#   Apps/Android/app/src/main/java/uniffi/carrier_core/carrier_core.kt   Kotlin API generated by UniFFI
#   Core/carrier-core/target/release/libcarrier_core.dylib   host build the JVM unit tests load
# Needs the Android NDK (ANDROID_NDK_HOME, or the newest under the SDK's ndk/) and cargo-ndk.
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
CRATE_DIR="$ROOT_DIR/Core/carrier-core"
ANDROID_APP="$ROOT_DIR/Apps/Android/app"
export PATH="$HOME/.cargo/bin:$PATH"

if [[ -z "${ANDROID_NDK_HOME:-}" ]]; then
  SDK_DIR="${ANDROID_HOME:-$(sed -n 's/^sdk.dir=//p' "$ROOT_DIR/Apps/Android/local.properties" 2>/dev/null)}"
  ANDROID_NDK_HOME="$(ls -d "$SDK_DIR"/ndk/* 2>/dev/null | sort -V | tail -1)"
  export ANDROID_NDK_HOME
fi
[[ -d "$ANDROID_NDK_HOME" ]] || { echo "Android NDK not found; set ANDROID_NDK_HOME" >&2; exit 1; }

cd "$CRATE_DIR"
cargo ndk -t arm64-v8a -t armeabi-v7a -t x86_64 -P 26 -o "$ANDROID_APP/src/main/jniLibs" build --release --lib
cargo build --release --lib
cargo run --quiet --bin uniffi-bindgen -- generate \
  --library "$CRATE_DIR/target/release/libcarrier_core.dylib" \
  --language kotlin --no-format --out-dir "$ANDROID_APP/src/main/java"

echo "Built Android libraries under $ANDROID_APP/src/main/jniLibs and Kotlin bindings under $ANDROID_APP/src/main/java/uniffi"
